class Solution:
    def longestCommonSubstring(self, text1, text2):
        if len(text2) > len(text1):
            text1, text2 = text2, text1
        prev = [0] * (len(text2) + 1)
        best = 0
        for a in text1:
            curr = [0] * (len(text2) + 1)
            for j, b in enumerate(text2, 1):
                if a == b:
                    curr[j] = prev[j - 1] + 1
                    best = max(best, curr[j])
            prev = curr
        return best

